import * as THREE from 'three';
import * as fs from 'fs';
import * as path from 'path';
import { createScene } from './data/object.js';

/**
 * Converts a Three.js scene to OBJ format with Blender Z-up coordinate system
 * Applies -90 degree X-rotation to convert from Y-up to Z-up
 */

// Create output directory if it doesn't exist
const outputDir = '/root/output';
if (!fs.existsSync(outputDir)) {
  fs.mkdirSync(outputDir, { recursive: true });
}

// Create the scene
const scene = createScene();

// Rotation matrix for -90 degrees around X axis (Y-up to Z-up conversion)
const rotationMatrix = new THREE.Matrix4();
const euler = new THREE.Euler(-Math.PI / 2, 0, 0, 'XYZ');
rotationMatrix.makeRotationFromEuler(euler);

// Collections for OBJ data
let vertices = [];
let faces = [];
let vertexMap = new Map(); // Map to deduplicate vertices
let vertexCount = 0;

/**
 * Convert vector position from Three.js Y-up to Blender Z-up
 */
function convertPosition(position) {
  const v4 = new THREE.Vector4(position.x, position.y, position.z, 1);
  v4.applyMatrix4(rotationMatrix);
  return new THREE.Vector3(v4.x, v4.y, v4.z);
}

/**
 * Create a unique key for vertex deduplication
 */
function getVertexKey(vertex) {
  return `${vertex.x.toFixed(6)},${vertex.y.toFixed(6)},${vertex.z.toFixed(6)}`;
}

/**
 * Process a single geometry and add its data to collections
 */
function processGeometry(geometry, worldMatrix) {
  if (!geometry) return;

  // Get position attribute
  const positions = geometry.getAttribute('position');
  if (!positions) return;

  const positionArray = positions.array;
  const isIndexed = geometry.getIndex() !== null;
  const indices = isIndexed ? geometry.getIndex().array : null;

  // Track vertex indices for this geometry
  const localVertexIndices = [];

  // Process vertices
  for (let i = 0; i < positionArray.length; i += 3) {
    const vertex = new THREE.Vector3(
      positionArray[i],
      positionArray[i + 1],
      positionArray[i + 2]
    );

    // Apply local transformations
    vertex.applyMatrix4(worldMatrix);
    // Apply coordinate system conversion
    vertex.applyMatrix4(rotationMatrix);

    const key = getVertexKey(vertex);

    // Deduplicate vertices
    if (!vertexMap.has(key)) {
      vertexMap.set(key, vertexCount);
      vertices.push(vertex);
      vertexCount++;
    }

    localVertexIndices.push(vertexMap.get(key));
  }

  // Process faces
  if (isIndexed) {
    for (let i = 0; i < indices.length; i += 3) {
      const a = localVertexIndices[indices[i]];
      const b = localVertexIndices[indices[i + 1]];
      const c = localVertexIndices[indices[i + 2]];
      faces.push([a + 1, b + 1, c + 1]); // OBJ uses 1-based indexing
    }
  } else {
    for (let i = 0; i < localVertexIndices.length; i += 3) {
      const a = localVertexIndices[i];
      const b = localVertexIndices[i + 1];
      const c = localVertexIndices[i + 2];
      faces.push([a + 1, b + 1, c + 1]);
    }
  }
}

/**
 * Recursively traverse scene and process all meshes
 */
function traverseScene(object, parentMatrix = new THREE.Matrix4()) {
  // Calculate world matrix for this object
  const matrix = new THREE.Matrix4();
  matrix.multiplyMatrices(parentMatrix, object.matrix);

  // If it's a mesh, process its geometry
  if (object instanceof THREE.Mesh) {
    console.log(`Processing mesh: ${object.name}`);
    processGeometry(object.geometry, matrix);
  }

  // If it's an InstancedMesh, process each instance
  if (object instanceof THREE.InstancedMesh) {
    console.log(`Processing instanced mesh: ${object.name} with ${object.count} instances`);
    const instanceMatrix = new THREE.Matrix4();
    const baseGeometry = object.geometry;

    for (let i = 0; i < object.count; i++) {
      object.getMatrixAt(i, instanceMatrix);
      const worldMatrix = new THREE.Matrix4();
      worldMatrix.multiplyMatrices(matrix, instanceMatrix);
      processGeometry(baseGeometry, worldMatrix);
    }
  }

  // Recursively process children
  for (const child of object.children) {
    traverseScene(child, matrix);
  }
}

console.log('Starting Three.js to OBJ conversion...');
traverseScene(scene);

console.log(`Total vertices: ${vertexCount}`);
console.log(`Total faces: ${faces.length}`);

// Generate OBJ file content
let objContent = '# Converted from Three.js scene\n';
objContent += `# Vertices: ${vertexCount}\n`;
objContent += `# Faces: ${faces.length}\n`;
objContent += '# Coordinate system: Blender Z-up (converted from Three.js Y-up)\n\n';

// Write vertices
for (const vertex of vertices) {
  objContent += `v ${vertex.x.toFixed(6)} ${vertex.y.toFixed(6)} ${vertex.z.toFixed(6)}\n`;
}

objContent += '\n';

// Write faces
for (const face of faces) {
  objContent += `f ${face[0]} ${face[1]} ${face[2]}\n`;
}

// Write to file
const outputPath = '/root/output/object.obj';
fs.writeFileSync(outputPath, objContent);

console.log(`\nOBJ file successfully exported to: ${outputPath}`);
console.log(`File size: ${(fs.statSync(outputPath).size / 1024).toFixed(2)} KB`);

